import sys
from graph import app

def process_query(user_query: str) -> None:
    """Runs a query through the Compiled LangGraph Application."""
    inputs = {"messages": [("user", user_query)]}
    
    try:
        output = app.invoke(inputs)
        # Extract and print final response generated by agent
        final_message = output["messages"][-1]
        print(f"\n[Agent Response]:\n{final_message.content}\n")
    except Exception as e:
        print(f"\n[Error executing query]: {e}\n", file=sys.stderr)

def main():
    print("=" * 60)
    print("      AI Agent Assistant")
    print(" Available static cities in database: London, Tokyo, New York, Paris")
    print("=" * 60)
    print("Type your query or type 'exit' / 'quit' to end.\n")

    while True:
        try:
            user_input = input("Enter prompt (e.g., 'What is the weather and info for Tokyo?'): ").strip()
            
            if not user_input:
                continue

            if user_input.lower() in ["exit", "quit", "q"]:
                print("Exiting application. Goodbye!")
                break

            process_query(user_input)

        except (KeyboardInterrupt, EOFError):
            print("\nTermination signal received. Exiting.")
            break

if __name__ == "__main__":
    main()